INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1099, 'koKR', 'Gobliny wygrywają!', '', '', '', 'Wróć do Rugfizzle\'a w Tysiącu Filarów.', '', '', '', '', 0),
(1100, 'koKR', 'Dziennik Lonebrowa', 'Powoli otwierasz sfatygowany dziennik Henriga Lonebrowa...', 'Przeczytaj dziennik Henriga Lonebrowa.', '', '', '', '', '', '', 0),
(1104, 'koKR', 'Jad z Solnisk', 'Mam tyle projektów dla naszego rakietowego samochodu! Tyle! I muszę wypróbować wszystkie!!$B$BPracuję nad nowym rodzajem paliwa. Takim, które pali się naprawdę, naprawdę, naprawdę gorąco!! Jeszcze nie dopracowałem mieszanki, ale chyba wiem, czego mi trzeba...$B$BSkorpiady, które wędrują po Migoczących Równinach, mają jad z mnóstwem, mnóstwem soli. Jest zupełnie wyjątkowy! I właśnie takiego potrzebuję!$B$BPrzynieś mi jad i zaufaj mi – nasz samochód poleci!!', 'Przynieś 6 porcji słonego jadu skorpiady Fizzle\'owi Mosiężnośrubowi na Migoczących Równinach.', '', 'Wróć do Fizzle\'a Mosiężnośruba na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1105, 'koKR', 'Utwardzone skorupy', 'Mój brat pracuje nad nowym paliwem do naszego rakietowego samochodu. Jest genialny, naprawdę. Tak genialny, że... chyba to nowe paliwo, które projektuje, jest tak silne, że przeżre podwozie na wylot!$B$BChcę wzmocnić zbiorniki paliwa, zanim do tego dojdzie.$B$BŻółwie na równinach mają bardzo twarde skorupy. Chcę z nich zrobić nowe zbiorniki do naszego rakietowego samochodu. Zbiorniki, które wytrzymają nowe paliwo mojego brata.$B$BWyglądasz na kogoś odpowiedzialnego. Przyniesiesz mi te skorupy?', 'Przynieś 9 utwardzonych skorup żółwia Wizzle\'owi Mosiężnośrubowi na Migoczących Równinach.', '', 'Wróć do Wizzle\'a Mosiężnośruba na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1106, 'koKR', 'Martek Wygnaniec', 'Buduję nowy silnik, dzięki któremu samochód będzie pędził jak szalony! Tak szybko, że poleci, wiem to! Muszę tylko zrobić tłoki, które wytrzymają bardzo, bardzo duże obciążenia. Wszystkie moje próby spełzły na niczym, bo nie umiem zrobić dość twardych tłoków!$B$BAle jest ktoś, kto może wiedzieć jak.$B$BNazywa się Martek Wygnaniec. To wielki kowal i wie o metalu więcej niż ktokolwiek. Zanieś mu ten list, wiem, że pomoże!$B$BAle on jest daleko, daleko – w Azeroth, na Bezludziu, w obozie, z goblinem!$B$BZnajdź go!', 'Zanieś list Fizzle\'a Martekowi Wygnańcowi na Bezludziu.', '', '', '', '', '', '', 0),
(1107, 'koKR', 'Obrośnięte płetwy ogonowe', 'Nasz rakietowy samochód to najszybsza rzecz na równinach! Tak szybka, że... boję się, że tarcie rozerwie go na kawałki!$B$BŻeby temu zapobiec, muszę stworzyć kompozyt do powlekania ruchomych części samochodu. Musi być twardy, ale nie kruchy, i odporny na korozję solną, bo inaczej Migoczące Równiny go zeżrą.$B$B$GSłyszałeś:Słyszałaś; o Plugawej Rafie, $N? Leży u wybrzeży Doliny Cierniodławów. Żyją tam murloki z plemienia Słonej Łuski, a ich płetwy ogonowe to kluczowy składnik mojego kompozytu.', 'Przynieś 10 obrośniętych płetw ogonowych Wizzle\'owi Mosiężnośrubowi na Migoczących Równinach.', '', 'Wróć do Wizzle\'a Mosiężnośruba na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1108, 'koKR', 'Indurium', 'Nie siedzę tu tylko po to, żeby trzymać się z dala od ludzi. Bezludzie kryje bogactwo metali, $N, o ile ktoś ma odwagę po nie sięgnąć.$B$BTen metal nazywa się indurium i, jak na zawołanie, podobno jest bardzo odporny na żar i obciążenia. Może się nadać do samochodu Fizzle\'a.$B$BAle upewnijmy się. Przynieś mi próbki indurium, a zbadam jego właściwości.$B$BPrawdziwa ruda indurium leży głęboko w Uldamanie, ale troggi z Kamiennego Skarbca na Bezludziu czasem mają przy sobie jego płatki. Przynieś mi je.', 'Przynieś 10 płatków indurium Martekowi Wygnańcowi na Bezludziu.', '', 'Wróć do Marteka Wygnańca w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(1110, 'koKR', 'Części samochodu rakietowego', 'He, he, przy tylu wyścigach, ile się tu odbywa, nic dziwnego, że czasem zdarzają się wypadki. Rozejrzyj się po Migoczących Równinach, a zobaczysz ślady dawnych kraks – wszędzie walają się szczątki rakietowych samochodów!$B$BA gnomy i gobliny płacą za te części. Ciągle szukają kolejnych ustrojstw, które mogą przykręcić do swoich samochodów.$B$BIdź więc i przynieś mi części. Przynieś całą stertę, a dobrze ci zapłacę.', 'Przynieś 30 części samochodu rakietowego Kravelowi Węglobrodemu na Migoczących Równinach.', '', 'Wróć do Kravela Węglobrodego na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1114, 'koKR', 'Dostawa dla gnomów', 'Teraz, kiedy mam to, czego potrzebuję, zanieś te części Fizzle\'owi Mosiężnośrubowi. Czeka na nie od dawna – na pewno nie zauważy braku tego drobiazgu, który wyjąłem z jego zamówienia...$B$BA ja bym mu o tym nie wspominał. To był mały, bezwartościowy kawałek.$B$BZaufaj mi.', 'Zanieś delikatne części samochodu Fizzle\'owi Mosiężnośrubowi na Migoczących Równinach.', '', '', '', '', '', '', 0),
(1115, 'koKR', 'Plotkarz', 'Skoro wyświadczyliśmy przysługę gnomom, czas zrobić coś dla goblinów!$B$BSłyszałem, że gobliński pilot wyścigowy, Nazz Parowar, nie zawsze nosił to nazwisko. Ciekawe, czemu je zmienił. Ciekawe, czy to tajemnica i... ciekawe, ile ta tajemnica jest dla niego warta.$B$BJeśli ktoś zna prawdę, to Krazek z Łupieżczej Zatoki, na południowym krańcu Cierniodławów. Porozmawiaj z Krazekiem i zapytaj go o naszego goblińskiego pilota.$B$BJeśli wyciągniesz od niego coś przydatnego, może uda nam się na tym zarobić.', 'Porozmawiaj z Krazekiem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(1117, 'koKR', 'Plotki dla Kravela', 'Musiałem skorzystać z kilku przysług, oddać rzadką butelkę elfiego wina i sam się sporo nagłówkować! Ale znalazłem informacje, których szukasz.$B$BProszę, spisałem list z kilkoma bardzo interesującymi szczegółami o naszym przyjacielu, Nazzie Parowarze. Zrób z nim, co chcesz – dla mnie jest zbyt niebezpieczny.$B$BTylko nikomu nie mów, skąd go masz!', 'Zanieś goblińskie plotki Kravelowi Węglobrodemu na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1118, 'koKR', 'Z powrotem do Łupieżczej Zatoki', '$N, jesteś kimś, komu mogę zaufać – i że wykonasz robotę, i że przy tym będziesz trzymać język za zębami.$B$BWymyśliłem nową intrygę. Jest ryzykowna, ale jeśli się uda, możemy na niej nieźle zarobić! I myślę, że jesteś właściwą osobą, żeby ją przeprowadzić.$B$BNa początek musisz wrócić do Łupieżczej Zatoki. Przepraszam, $gdrogi:droga; $N. Wiem, że moje ostatnie zadanie już cię tam zaprowadziło. Ale tym razem porozmawiaj z Crankiem Fizzlebubem.$B$BDaj mu ten list. A jeśli będzie potrzebował pomocy, zrób, co w twojej mocy. Opłaci się.', 'Zanieś intrygę Kravela Crankowi Fizzlebubowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(1119, 'koKR', 'Mikstura Zanzila i stout głupca', 'Wymyśliłem, jak połączyć miksturę Zanzila ze stoutem, żeby otrzymać mocny trunek. Stout głupca. Myślę, że to dokładnie to, czego potrzebuje Kravel, ale wypróbuj go i daj mi znać, jak działa.$B$BI, $N, nie trzymaj tego zbyt długo bez użycia. Mikstura Zanzila dziwnie działa na drożdże w stoucie i podkręca je na najwyższe obroty. Nie będzie więc świeży w nieskończoność.', 'Zanieś stout głupca Kravelowi na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1120, 'koKR', 'Upij gnomy', 'Musimy wypróbować stout głupca na jednej z ekip serwisowych. Jeśli chcesz spróbować na gnomach, to proszę – weź stout i daj go gnomiemu szefowi serwisu.$B$BI nie zwlekaj zbyt długo. Ten stout w końcu się zepsuje.', 'Zanieś stout głupca gnomiemu szefowi serwisu na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1121, 'koKR', 'Upij gobliny', 'Musimy wypróbować stout głupca na jednej z ekip serwisowych. Jeśli chcesz spróbować na goblinach, to proszę – weź stout i daj go goblińskiemu szefowi serwisu.$B$BI nie zwlekaj zbyt długo. Ten stout w końcu się zepsuje.', 'Zanieś stout głupca goblińskiemu szefowi serwisu na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1122, 'koKR', 'Zamelduj się u Fizzlebuba', 'Ten stout głupca zadziałał świetnie! Postawiłem na następny wyścig i... miejmy nadzieję, że ekipa, którą $gupiłeś:upiłaś;, porządnie namieszała przy swoim samochodzie!$B$BZostało dla ciebie tylko jedno zadanie – zanieś tę notatkę Crankowi Fizzlebubowi w Łupieżczej Zatoce. Będzie chciał się dowiedzieć o udanej próbie.$B$BI oby udało nam się zdobyć więcej tego stoutu głupca na przyszłe wyścigi!', 'Zanieś raport o stoucie głupca Crankowi Fizzlebubowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(1128, 'koKR', '<NYI> Gnomia ekipa serwisowa ma pragnienie', '', '', '', 'Wróć do gnomiego szefa serwisu w Tysiącu Filarów.', '', '', '', '', 0),
(1129, 'koKR', '<NYI> Goblińska ekipa serwisowa ma pragnienie', '', '', '', 'Wróć do goblińskiego szefa serwisu w Tysiącu Filarów.', '', '', '', '', 0),
(1137, 'koKR', 'Wieści dla Fizzle\'a', 'Indurium jest niesamowicie odporne na żar! Jestem pewien, że sprawdzi się w tłokach Fizzle\'a. Ale będzie potrzebował prawdziwej rudy indurium, a nie samych płatków.$B$BTę rudę trzeba wydobyć z głębin Uldamanu, na północnych rubieżach Bezludzia. To tam jest prawdziwe źródło indurium.$B$BPozdrów ode mnie Fizzle\'a Mosiężnośruba i powtórz mu, co ci powiedziałem.$B$BBezpiecznej podróży, $N. I nie zdziwię się, jeśli jeszcze się spotkamy – gdy Fizzle dowie się o indurium, pewnie wyśle cię do Uldamanu, żebyś je $gzdobył:zdobyła;!', 'Porozmawiaj z Fizzle\'em Mosiężnośrubem na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1147, 'koKR', '', 'Hmm. Wygląda na to, że Belgrom uważa te potwory za zagrożenie. Chce, żeby zepchnąć je z powrotem w głębiny, z których wypełzły.$B$BWidać zabicie krasnoludów przysłanych przez Ligę Odkrywców to było za mało – teraz muszę posłać do kolejnej bitwy na wpół martwy oddział wojenny. Sami nie damy rady, nie w takim stanie. Wykopalisko jest na południe stąd. Krasnoludów raczej już tam nie będzie. Czujesz się na siłach, by chwycić za ostrze lub kostur i dołożyć swoją cegiełkę?', 'Zabij 5 silithidów poszukiwaczy, 5 silithidów robotników roju i 5 silithidów najeźdźców, a następnie wróć do Moktara Krina w Tysiącu Filarów.', '', 'Wróć do Moktara Krina w Obozie Żelaznego Kamienia w Tysiącu Filarów.', '', '', '', '', 0),
(1149, 'koKR', 'Próba wiary', 'A więc $godszukałeś:odszukałaś; mnie, a może to przeznaczenie cię do mnie przywiodło? Nieważne. Jesteś tu teraz, więc twoja wędrówka zacznie się na nowo.$B$BNa istotę składa się wiele stron: duch, ciało, umysł. Niektóre z nich można zmierzyć tradycjami danej kultury. Co do innych możemy jedynie mieć nadzieję, że w nas istnieją. Jeśli się zgodzisz, poddam próbie niektóre z tych stron w tobie.$B$BJeśli przejdziesz próby, staniesz się $gsilniejszy:silniejsza;. Jeśli zawiedziesz, pojmiesz ogrom Otchłani.$B$BPierwsza jest próba wiary.', 'Jeśli masz wiarę, skocz z pomostu wiszącego nad Tysiącem Filarów.', '', 'Wróć do Dorna Tropiciela Równin w Kanionie Wiatrołomu w Tysiącu Filarów.', '', '', '', '', 0),
(1150, 'koKR', 'Próba wytrzymałości', 'Cieszę się, że twoja odwaga nie słabnie mimo tego, czego już $gdokonałeś:dokonałaś;. Skoro twoja wiara pozostała nienaruszona, nadszedł czas, by poddać próbie twoje ciało.$B$BNajpierw próba wytrzymałości. Udaj się do Nory Łotrzych Piór na zachód od Posterunku Wolnego Wiatru. Przedrzyj się w głąb ich legowiska i zniszcz ich zapasy żywności. To powinno rozbudzić ich furię, a jeśli zdołasz przetrwać wystarczająco długo, przyjdzie po ciebie sama Grenka Krwawy Wrzask – zabij ją i przynieś mi jej pazur, by ukończyć próbę.', 'Przynieś pazur Grenki Dornowi Tropicielowi Równin w Tysiącu Filarów.', '', 'Wróć do Dorna Tropiciela Równin w Kanionie Wiatrołomu w Tysiącu Filarów.', '', '', '', '', 0),
(1151, 'koKR', 'Próba siły', 'W czasach Przedwiecznych Bogów żywiołaki zamieszkiwały znaczną część tego świata. Oddawały cześć Przedwiecznym, a Bogowie swoją mocą wiązali żywiołaki z tym światem. Gdy Przedwieczni zostali wygnani, żywiołaki zniknęły z naszego świata i teraz powracają jedynie na wezwanie potężnych magów.$B$BSą jednak wyjątki. Niektóre żywiołaki były na tyle potężne, by pozostać tu same z siebie. Jednym z nich jest Rok\'Alim.$B$BAby sprawdzić twoją siłę, odnajdź Rok\'Alima w Tysiącu Filarów i zabij go.', 'Przynieś fragmenty Rok\'Alima Dornowi Tropicielowi Równin w Tysiącu Filarów.', '', 'Wróć do Dorna Tropiciela Równin w Kanionie Wiatrołomu w Tysiącu Filarów.', '', '', '', '', 0),
(1165, 'koKR', '<NYI> Ruda na wyścigi', '', '', '', 'Wróć do Fizzle\'a Mosiężnośruba w Tysiącu Filarów.', '', '', '', '', 0),
(1174, 'koKR', 'Gnomy wygrywają!', '', '', '', 'Wróć do Crazzle\'a Żwawotryba w Tysiącu Filarów.', '', '', '', '', 0),
(1175, 'koKR', 'Wybój na drodze', 'Po wielkiej kraksie goblińskiej wyścigówki Czerwony Grom z bazyliszkiem Kronkrider zatrudnił mnie do dbania o tor. Nie wiem, czym żywią się te wszystkie zwierzęta na równinach, że tak wyrastają, ale musimy je uważnie przetrzebiać, żeby nie wchodziły na tor w trakcie wyścigu.$b$bWiesz co? Jeśli chcesz trochę zarobić, ruszaj i pozbądź się bazyliszków z okolicy.', 'Zabij 10 solnokamiennych bazyliszków, 10 solnokamiennych kryształoskórów i 6 solnokamiennych obserwatorów dla kierownika toru Zherina na Migoczących Równinach.', '', 'Wróć do kierownika toru Zherina na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1176, 'koKR', 'Odchudzanie ładunku', 'W wyścigach liczy się każdy drobiazg! Czy to drobna poprawka mocy wyjściowej, lekkie poluzowanie cewek napinających, czy odchudzenie ramy – trzeba brać pod uwagę wszystko.$b$bDo wielu drobnych poprawek konstrukcyjnych w naszych wyścigówkach używamy kości sępów, które mają idealny stosunek wytrzymałości do wagi. Co lepsze, łatwo je zdobyć, bo na solniskach aż roi się od sępów.$b$bPrzynieś mi trochę, a dobrze ci za nie zapłacę.', 'Zdobądź 10 pustych kości sępa dla Pozzika na Migoczących Równinach.', '', 'Wróć do Pozzika na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1181, 'koKR', '', 'Obawiam się, że niewiele więcej mogę ci pomóc, $n. Jeśli chcesz dalej to drążyć, radzę udać się do samego barona. Jeśli ktoś się zna na interesach Revilgaza, to właśnie Revilgaz.$b$bZnajdziesz go w tawernie po drugiej stronie portu, na najwyższym piętrze.', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce.', '', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1182, 'koKR', '', 'Widzisz, rozdrabniacze spółki Gitgeszeft nad Jeziorem Nazferiti (w północnych Cierniodławach) wyposażono w nowy model regulatora paliwa. Pomyślałem, że Pozzik mógłby to wykorzystać, gdyby poznał szczegóły. Niestety Cozzle, tamtejszy brygadzista, okazał się nieco sprytniejszy, niż sądziłem.$b$bTy jednak wyglądasz na kogoś, komu może się poszczęścić przy szukaniu tych planów. Wiem, że trzyma je w swoim domu, ale niemal na pewno pod kluczem.', 'Przynieś plany regulatora paliwa baronowi Revilgazowi w Łupieżczej Zatoce.', '', 'Wróć do barona Revilgaza w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1183, 'koKR', '', 'Wszystko gotowe, możesz ruszać. Pozdrów ode mnie Pozzika i powiedz mu, że jeśli kiedykolwiek będzie czegoś potrzebował, niech śmiało prosi. Czekam na wieść, że wkrótce pobije rekord toru!', 'Dostarcz plany regulatora paliwa Pozzikowi na Migoczących Równinach.', '', 'Wróć do Pozzika na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', 0),
(1186, 'koKR', 'Osiemnasty pilot', 'Będę zajęty montowaniem nowego regulatora paliwa w naszych wyścigówkach, ale jeśli chcesz jeszcze pomóc drużynie, zagadaj do Razzerica. To nasz pilot – no, dokładniej nasz osiemnasty pilot – i lubi dodawać do wyścigówek własne drobne modyfikacje.$b$bMa jednak trochę nie po kolei w głowie, więc staraj się nie okazywać zbytniego zdziwienia.', 'Odszukaj Razzerica na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1187, 'koKR', 'Poprawki Razzerica', 'Pozzik to świetny mechanik, wiem, ale boi się po prostu dołożyć mocy i trzymać się mocno. Ja się nie boję.$b$bKiedy Pozzik skończy z wyścigówką, poświęcam chwilę na własne modyfikacje – no wiesz, luzuję sterowanie, wywalam kawałki ramy i dokładam więcej mocy!$b$bZamówiłem dopalacz z seaforium u Shreeva w Gadżetorium w Gadżetonie, ale podobno sterowiec, którym go wysłano, rozbił się na Pyłowym Bagnisku! Muszę go mieć, $n!', 'Odzyskaj dopalacz z seaforium dla Razzerica na Migoczących Równinach.', '', 'Wróć do Razzerica na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1188, 'koKR', 'Bezpieczeństwo przede wszystkim', 'Ale chwila, co to? Shreev zostawił włączoną blokadę. To ograniczy moc, jaką w danej chwili mogę czerpać z dopalacza. Mówiłem mu, że ma być wyłączona! Tak być nie może.$b$bMusisz zanieść to do Gadżetorium w Gadżetonie na pustyni Tanaris i kazać Shreevowi ją zdjąć.', 'Zanieś dopalacz z seaforium Shreevowi w Gadżetonie w Tanaris.', '', '', '', '', '', '', 0),
(1189, 'koKR', 'Bezpieczeństwo przede wszystkim', 'Proszę, zrobiłem to, czego chciał Razzeric. Powiedz mu tylko, żeby uważał, kiedy będzie to odpalał. Jeśli popełni choćby najmniejszy błąd, nie pomknie naprzód, tylko zostanie z niego osmalona plama na torze.$b$bA szkoda by było. Kto wie, czy nasz dziewiętnasty kierowca byłby coś wart?', 'Zanieś zmodyfikowany dopalacz z seaforium Razzericowi na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1190, 'koKR', 'Dotrzymać kroku', 'Bracia Mosiężnośrubowie odkryli nowy materiał konstrukcyjny, to jedyne sensowne wyjaśnienie. Ich samochody jeżdżą szybciej niż wcześniej, a przecież ich projekty i wszystkie inne dane, jakie zebraliśmy z ich przejazdów, się nie zmieniły.$b$bWiemy tyle, że Rizzle Mosiężnośrub niemal bez przerwy ślęczy nad planami tego nowego odkrycia.$b$bZamek może odwrócić ich uwagę, żebyś $gmógł:mogła; wykraść im te plany.', 'Niech Zamek odwróci uwagę, a potem wykradnij plany Rizzle\'a dla Pozzika na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1191, 'koKR', 'Dywersja Zamka', '', '', '', '', '', '', '', '', 0),
(1192, 'koKR', 'Ruda indurium', '', '', '', 'Wróć do Pozzika w Tysiącu Filarów.', '', '', '', '', 0),
(1194, 'koKR', 'Schematy Rizzle\'a', 'Schematy Rizzle\'a opisują proces rafinacji rudy indurium. Z jego bazgrołów wynika, że ruda indurium pochodzi z krasnoludzkiego wykopaliska w Uldamanie na Bezludziu.$b$bWiększość pozostałych notatek dotyczy odporności na żar.$b$bJako przycisk do papieru na planach leży bryłka czegoś, co wygląda na nierafinowaną rudę indurium.', 'Zanieś próbkę rudy indurium Pozzikowi na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1949, 'koKR', 'Ukryte sekrety', 'Aby wykonać twoją różdżkę, muszę przeczytać kluczowe fragmenty pewnej księgi. Nazywa się „Rytuały mocy” i napisał ją mag Tirth.$B$BNie mam egzemplarza jego księgi, a żadna z wielkich bibliotek świata jej nie posiada. Musisz więc porozmawiać z Tirthem i zdobyć ją od niego.$B$BPowodzenia. Tirth był kiedyś wielkim magiem i uczonym, ale teraz przesiaduje na wyścigach gnomów i goblinów na Migoczących Równinach, gdzie pije i uprawia hazard.', 'Porozmawiaj z magiem Tirthem na Migoczących Równinach.', '', '', '', '', '', '', 0),
(1950, 'koKR', 'Zasięgnij języka', 'Mogę ci pomóc z księgą, ale najpierw ty musisz pomóc mnie!$B$BTom, którego szukasz, leży w mojej magicznie zamkniętej szkatule. Żeby ją otworzyć, trzeba wypowiedzieć specjalną formułę, a ja jej nie pamiętam! Zwykle przypomina mi takie rzeczy mój asystent, ale nigdzie go nie ma.$B$BJeśli chcesz dostać moją księgę, znajdź mojego ucznia! Popytaj na torze wyścigowym – jeśli dopisze ci szczęście, ktoś go widział. Albo przywlecz go tutaj, albo przynajmniej wyciągnij z niego moją magiczną formułę, żebyśmy mogli otworzyć szkatułę!', 'Poznaj formułę otwierającą szkatułę Tirtha, a następnie wróć do niego.', 'Poznano tajną formułę', 'Wróć do maga Tirtha na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(1951, 'koKR', 'Rytuały mocy', 'Hm... teraz, kiedy o tym myślę, nie mam swojej księgi! Widzisz, miałem długi hazardowe i żeby je spłacić, sprzedałem ostatni egzemplarz „Rytuałów mocy” pewnemu duchownemu...$B$BCzłonkowi Szkarłatnego Bractwa. Pewnie zabrał go do ich biblioteki w Szkarłatnym Klasztorze na Polanach Tirisfal!$B$BJeśli chcesz tę księgę, musisz udać się do klasztoru i jej poszukać. I przepraszam za kłopot. Ostatnio nie jestem sobą...', 'Zanieś księgę „Rytuały mocy” do Tabethy na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(2770, 'koKR', 'Gahz\'rilla', 'Głęboko w Zul\'Farrak, mieście piaskowych trolli w Tanaris, jest święta sadzawka. Z tej sadzawki trolle przyzywają ogromną bestię! Gahz\'rillę! Jest tak dziki, że nawet jego łuski trzeszczą od energii. To właśnie tę energię chcę okiełznać dla mojego samochodu!$B$BPrzynieś mi naelektryzowaną łuskę Gahz\'rilli!$B$BAle przyzywanie Gahz\'rilli to pilnie strzeżony sekret trolli. Żeby stanąć z nim do walki, musisz najpierw wydrzeć im ten sekret.', 'Przynieś naelektryzowaną łuskę Gahz\'rilli Wizzle\'owi Mosiężnośrubowi na Migoczących Równinach.', '', 'Wróć do Wizzle\'a Mosiężnośruba na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(3841, 'koKR', 'Sierota szuka domu', 'Och, witaj, $N. Tak się cieszę, że znów cię widzę. Jak minęła podróż do Darnassus?$B$BCóż, ucieszy cię wiadomość, że podczas twojej nieobecności zrobiłyśmy spore postępy. Uratowałyśmy nawet gniazdo pełne jaj. Niestety matka zginęła, zanim do niej dotarłyśmy.$B$BSłuchaj, chcesz jedno jako zwierzątko? Wygląda na to, że wkrótce się wyklują, więc będą potrzebowały $Gdobrego ojca:dobrej matki;. Co ty na to?$B$BJeśli naprawdę chcesz, zanieś jedno z jaj Quentinowi na tor wyścigowy na Migoczących Równinach. On powie ci więcej.', 'Porozmawiaj z Quentinem w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(3842, 'koKR', 'Krótka inkubacja', 'Tkaczki Księżyca, co? Bardzo intrygujące. Szkoda, że duszkowce nie potrafią naprawdę docenić, co to znaczy mieć takie dwie opiekunki. Obie są bardzo kompetentne.$B$BWięc dały ci jajo w prezencie. W takim razie to ty masz się nim opiekować, jak długo zechcesz. Wygląda na to, że niemal jest gotowe do wyklucia, ale powinniśmy się upewnić, że jest zdrowe i nic mu się nie stało.$B$BPotrzebuję tylko dwóch eliksirów wytrwałości do drobnego zaklęcia chroniącego jajo. Resztę składników mam przy sobie.', 'Przynieś 2 eliksiry wytrwałości Quentinowi w Tysiącu Filarów.', '', 'Wróć do Quentina na Torze Wyścigowym Miraż w Tysiącu Filarów.', '', '', '', '', 0),
(3843, 'koKR', 'Najnowszy członek rodziny', 'Wspaniały okaz, $N. Jeśli to stworzenie przetrwa inkubację, wyrośnie na naprawdę zdrowego pupila!$B$BJeśli zamierzasz doprowadzić sprawę do końca, radziłbym zrobić jeszcze jedno – udaj się do Orlego Gniazda w Zaziemiu. Porozmawiaj tam z krasnoludem imieniem Agnar Poskramiacz Bestii. To mistrz w obchodzeniu się ze zwierzętami i powinien poprowadzić cię przez ostatnie etapy inkubacji.$B$BAle pośpiesz się, $N, to jajo jest kruche i bez należytej opieki długo nie przetrwa.', 'Zanieś kruche jajo duszkowca do Zaziemia i porozmawiaj z Agnarem Poskramiaczem Bestii, ale pośpiesz się – masz tylko 1 godzinę, by go odnaleźć, zanim pisklę w jaju zginie.', '', '', '', '', '', '', 0),
(4323, 'koKR', '<NYI> <TXT> Dorwij te hieny!!!', 'Chcę futer hien, i to tylko najlepszych! Przynieś mi futra cętkowanych hien, a dam ci wypasione łupy, ziom.', 'Przynieś 7 futer cętkowanej hieny TESTTAUREN na Posterunku Wolnego Wiatru.', '', '', '', '', '', '', 0),
(4542, 'koKR', 'Wiadomość dla Posterunku Wolnego Wiatru', '$GDzielny podróżniku:Dzielna podróżniczko;, centaury nasiliły ataki w tej okolicy. Posterunek Wolnego Wiatru musi się natychmiast dowiedzieć o tych nowych napaściach! Odszukaj wartownika urwisk Długoroga na Posterunku Wolnego Wiatru na południowym wschodzie i przekaż mu tę pilną wiadomość.$b$bUważaj i omijaj pobliski klan Ponurego Totemu... ostatnio dziwnie się wobec nas zachowują.$B$B', 'Zanieś pilną wiadomość wartownikowi urwisk Długorogowi na Posterunku Wolnego Wiatru.', '', '', '', '', '', '', 0),
(4767, 'koKR', 'Jeździec wiwern', 'Powierzono mi zadanie pozyskania kolejnych wiwern dla mistrzów wiwern. Jest ich coraz więcej, a ja sam mam nadzieję, że pewnego dnia zostanę jeźdźcem wiwern. Nie jesteśmy jednak w stanie wyszkolić tylu wiwern, by nadążyć za zapotrzebowaniem. Może ty mi pomożesz, $N.$B$BMusisz udać się na Wysoką Grzędę i zebrać trochę jaj wiwern. Stąd kieruj się na północny zachód wzdłuż ścian kanionu, aż dojdziesz do pochylni prowadzącej na Wysoką Grzędę. Uważaj, wiwerny zażarcie bronią swoich jaj i nie będą łaskawe dla intruzów.', 'Przynieś 10 jaj wiwerny z Wysokiej Grzędy Elu w Posterunku Wolnego Wiatru.', '', 'Wróć do Elu w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(4770, 'koKR', 'Droga do domu', 'Pomóż mi, proszę, $N! Ukrywam się tu, na Wysokiej Grzędzie, od dłuższego czasu i od wielu dni nie widziałem przyjaznej twarzy. Przybyłem tu badać wiwerny i chyba podszedłem trochę za blisko. Gdy przegoniono mnie od jednego z gniazd, zgubiłem się.$B$BMuszę wrócić do Posterunku Białego Zasięgu! Motega nie wie, że zniknąłem, i wpadnie we wściekłość, gdy się dowie, że sam zapuściłem się na Wysoką Grzędę.$B$BPosterunek Białego Zasięgu leży tuż na wschód stąd... proszę, zaprowadź mnie tam!', 'Odeskortuj Pao\'kę Rączą Górę z Wysokiej Grzędy, a następnie porozmawiaj z Motegą Ognistą Grzywą w Posterunku Białego Zasięgu.', 'Odeskortuj Pao\'kę z Wysokiej Grzędy', 'Wróć do Motegi Ognistej Grzywy w Tysiącu Filarów.', '', '', '', '', 0),
(4821, 'koKR', 'Obce jajo', 'Krąży plotka o obcym jaju tu, w Tysiącu Filarów. Ci, którzy twierdzą, że je widzieli, nie zdołali nawet podejść dość blisko, by mu się dokładnie przyjrzeć. Węże strzegą jaja, jakby było jednym z ich własnych.$B$BChcę, żebyś $godnalazł:odnalazła; to obce jajo i $gprzyniósł:przyniosła; je do mnie, abym mógł je zbadać. Według doniesień jajo leży w wężowym legowisku, ale u podnóża skalnych ścian na południe i północny wschód od Posterunku Wolnego Wiatru jest kilka takich legowisk.', 'Dostarcz obce jajo Hagarowi Piorunowemu Kopytu w Posterunku Wolnego Wiatru.', '', 'Wróć do Hagara Piorunowego Kopyta w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(4841, 'koKR', 'Spacyfikuj centaury', '$N, błagam cię, wytrop te centaury. Poczują gniew naszej zemsty. Zaatakuj obóz centaurów na północ od Posterunku Wolnego Wiatru! Niech gniew prowadzi twoją rękę!$B', 'Zabij 12 zwiadowców Galaków, 10 poskramiaczy Galaków i 6 łowczyń wiatru Galaków, a następnie wróć do wartownika urwisk Długoroga w Posterunku Wolnego Wiatru.', '', 'Wróć do wartownika urwisk Długoroga w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(4865, 'koKR', 'Wąż na wolności', 'Gdybym nie zobaczył tego na własne oczy, nigdy bym nie uwierzył, że to prawda. Pomsta przybyła do Tysiąca Filarów!$B$B<Hagar ociera czoło.>$B$B$N, musisz działać szybko! Idź natychmiast do Motegi Ognistej Grzywy. Znajdziesz go w Posterunku Białego Zasięgu, przy drodze na północny zachód od Posterunku Wolnego Wiatru. On będzie wiedział, co robić!', 'Przekaż, czego się $gdowiedziałeś:dowiedziałaś;, Motedze Ognistej Grzywie w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(4881, 'koKR', 'Spisek zamachowców', 'Tauren Kanati Szara Chmura zuchwale rozbił obóz łowiecki w Tysiącu Filarów. Musimy go zabić, by pozbyć się tego obozu i wszystkich, którzy mogliby pójść w jego ślady. Zbierzemy się przy małym posterunku na południowy zachód od Wielkiej Windy.$B', 'Ostrzeż Kanatiego Szarą Chmurę w Posterunku Białego Zasięgu przed spiskiem na jego życie.', '', '', '', '', '', '', 0),
(4904, 'koKR', 'Nareszcie na wolności', 'Arnak myśli, że się pobierzemy... ale gdy odrzuciłam jego oświadczyny, wrócił tej samej nocy i mnie porwał. Mój brat próbował go powstrzymać, ale Arnak był za silny. On... zabił mojego brata, a potem przywlókł mnie tutaj. Mój biedny brat...$B$B$N, czy możesz wyprowadzić mnie ze Szczytu Mrocznej Chmury? Proszę... Muszę wrócić do Thalii! Na pewno umiera ze zmartwienia.', 'Odeskortuj Lakotę Pieśń Wiatru ze Szczytu Mrocznej Chmury, a następnie porozmawiaj z Thalią Bursztynową Skórą w Posterunku Wolnego Wiatru.', 'Odeskortuj Lakotę Pieśń Wiatru ze Szczytu Mrocznej Chmury.', 'Wróć do Thalii Bursztynowej Skóry w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(4966, 'koKR', 'Obrona Kanatiego Szarej Chmury', 'Ale centaurów może być więcej, niż sądziłem. Proszę cię, $n, stań ze mną do walki z tymi podłymi zabójcami.', 'Ochroń Kanatiego Szarą Chmurę przed atakiem centaurów.', 'Ochroń Kanatiego Szarą Chmurę', 'Wróć do Kanatiego Szarej Chmury w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', 0),
(5064, 'koKR', 'Szpiegowanie Ponurego Totemu', '$N, dobrze nam $gsłużyłeś:służyłaś; w przeszłości, więc teraz powierzam ci ważną misję. Klan Ponurego Totemu coś potajemnie knuje. W ostatnich tygodniach widziano trzech agentów nieznanego pochodzenia, którzy odwiedzali Ponure Totemy. Odkryliśmy, że te pilnie strzeżone wiadomości są przechowywane w osobnych skrzyniach na Szczycie Mrocznej Chmury.$b$b$N, jeśli powiedzie ci się ta niebezpieczna misja, godnie cię wynagrodzę.$B', 'Odnajdź i zabierz trzy tajne notatki ze Szczytu Mrocznej Chmury.', '', 'Wróć do wartownika urwisk Długoroga w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(5147, 'koKR', 'Poszukiwany: Arnak Ponury Totem', 'Poszukiwany: Arnak Ponury Totem$B$BWygnaniec Arnak jest poszukiwany za haniebne zbrodnie morderstwa i porwania. Sowita nagroda czeka na śmiałków, którzy postawią tego zbrodniarza przed obliczem sprawiedliwości.$B$BArnaka ostatnio widziano na urwiskach w pobliżu Szczytu Mrocznej Chmury. Aby odebrać nagrodę, pokaż dowód swojego czynu wartownikowi urwisk Długorogowi w Posterunku Wolnego Wiatru.', 'Zabij Arnaka Ponurego Totemu i przynieś dowód swojego czynu wartownikowi urwisk Długorogowi w Posterunku Wolnego Wiatru.', '', 'Wróć do wartownika urwisk Długoroga w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(5151, 'koKR', 'Hiperkondensatorowy gadżet', 'Jestem jedynym, kto ocalał z naszej karawany po ataku centaurów! Rzadka, lecz potężna pantera strzeże mojego najlepszego gadżetu, który ma zawieszony na szyi. Ha! Nawet centaury drżą w obecności tej dzikiej bestii!$B$BOto klucz do klatki. Zabrali stamtąd wszystko, ale jego zostawili w spokoju. Zabij bestię i przynieś mój hiperkondensator, a wynagrodzę cię.$b$bWrak karawany jest tuż na północ stąd.$B', 'Zabij bestię i przynieś hiperkondensatorowy gadżet oraz klucz do klatki pantery Wizlowi Polerołożyskowi.', '', 'Wróć do Wizla Polerołożyska w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', 0),
(5762, 'koKR', 'Hemet Nesingwary junior', 'Mam paczkę dla nowego klienta, krasnoluda nazwiskiem Hemet Nesingwary junior. Paczka szła całe tygodnie i Hemeta dawno już tu nie ma. Mówił, że wybiera się do Cierniodławów, by zająć miejsce ojca i polować tam na zwierzynę, ale zostawił mi trochę pieniędzy, żebym wysłał przesyłkę, kiedy będę mógł.$B$BJunior to bogaty krasnolud, a z bogaczami warto trzymać sztamę, no nie? No to... dostarczysz za mnie tę paczkę?$B$BSłyszałem, że ma obóz w Cierniodławach, na północ od Grom\'gol.', 'Zanieś skrzynkę Kravela Hemetowi Nesingwary\'emu juniorowi w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(9431, 'koKR', 'Inne podejście', 'Co robi sin\'dorei na szczycie smaganego wiatrem ostańca w Tysiącu Filarów, zamiast przechadzać się po salach Srebrnej Luny?$B$BTo proste. Pobratymcy nie chcą mnie już znać. Spalono każdy egzemplarz mojego traktatu o naturalnych lekach na nasze uzależnienie od magii.$B$BTu mogę bezpiecznie prowadzić badania, ale brakuje mi składników. Byłabym wdzięczna, gdybyś $gzebrał:zebrała; oczyszczającą ziemię z grzmiących głazowców w pobliżu zachodniego krańca Filarów i $gdostarczył:dostarczyła; ją mojemu wspólnikowi w Posterunku Białego Zasięgu.', 'Zbierz 2 garście oczyszczającej ziemi z grzmiących głazowców i zanieś je Wizlowi Polerołożyskowi w Posterunku Białego Zasięgu.', '', 'Wróć do Wizla Polerołożyska w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', 0),
(9433, 'koKR', 'Kąpiel w księżycowej studni', 'Nie patrz tak na mnie! Nie mówiłem, że wyślę cię do księżycowej studni w Thalanaar, na widoku, z chochlą i flaszką!$B$BJa, eee... majstrowałem trochę przy towarze, który przewoziłem dla klienta. Prawdę mówiąc, już ustawiłem przenośny panel sterowania Robotronem niedaleko Thalanaar. Weź ze sobą ten moduł sterujący i użyj go w pobliżu mojego ukrytego panelu.$B$BGdyby mój klient usłyszał, że choćby wyjąłem Robotrona z opakowania, powiesiłby mnie za uszy!', 'Użyj modułu sterującego Robotrona, stojąc przy ukrytym panelu sterowania schowanym w kępie krzaków na krawędzi filaru najbliższego Thalanaar, aby przejąć kontrolę nad Robotronem 3000. Poprowadź robota na zachodni skraj Tysiąca Filarów, gdzie leży placówka Przymierza Thalanaar. Za pomocą robota pobierz próbkę wody z księżycowej studni i zanieś ją Wizlowi Polerołożyskowi w Posterunku Białego Zasięgu.', '', 'Wróć do Wizla Polerołożyska w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', 0),
(9434, 'koKR', 'Próba toniku', '<Wizlo wyjmuje z robota próbkę wody i wkłada ją do skrzynki razem z ziemią z głazowców i kilkoma innymi przedmiotami.>$B$BProszę bardzo, to wszystko z listy magistrix Elosai. Powiedz jej, że współpraca z nią była przyjemnością i że życzę jej powodzenia w badaniach.', 'Dostarcz skrzynkę ze składnikami magistrix Elosai w Posterunku Wolnego Wiatru.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(1100, 'koKR', 'Mówisz, że $gznalazłeś:znalazłaś; ten dziennik przy martwym krasnoludzie? Daj mi chwilę, niech przejrzę jego strony...', 0),
(1104, 'koKR', 'Super! Ten jad sprawdzi się znakomicie! Dzięki, $N!$b$bTeraz tylko muszę go odparować, zastosować skiperotomer, dodać negakatalizator i... Kurczę! Gdzie są moje notatki?!', 0),
(1105, 'koKR', 'Masz je! Dzięki, $N!$B$BRany, te skorupy są twardsze, niż myślałem! Do pracy z nimi będę chyba potrzebował całej skrzyni narzędzi!', 0),
(1106, 'koKR', 'Fizzle cię przysłał? To zmienia postać rzeczy! Oczywiście, że ci pomogę. Fizzle i jego brat to jedni z niewielu, którzy nie życzą mi śmierci!$b$bWięc Fizzle chce zrobić tłoki, co? Tłoki na tyle mocne, żeby wytrzymały wszystko, co zaplanował – a jeśli znam Fizzle\'a, to ten jego nowy samochód jest wulkanem na kołach!', 0),
(1107, 'koKR', 'Dziękuję, $N! Kiedy je zmielę i stopię z kilkoma innymi składnikami, kompozyt będzie gotowy. A wtedy samochodowi nie zagrozi już jego własna prędkość.$b$bNie zagrozi, dopóki w nic nie uderzy...', 0),
(1108, 'koKR', 'Ach tak, te się nadadzą. Teraz wystawmy je na żar i zobaczmy, jak się sprawią...', 0),
(1110, 'koKR', 'No proszę, patrzcie no! W tej stercie złomu jest trochę dobrego towaru. Na pewno opchnę go za niezłą sumkę.$b$bA czy to... ucho wciśnięte między te dwie blachy?? Au! He, nie chciałbym być tym pilotem!$b$bDzięki, $N. Oto twoja zapłata. A tu rada, gratis...$b$bJeśli dobrze się rozejrzysz, zawsze znajdziesz zysk w cudzej tragedii.', 0),
(1114, 'koKR', 'Są! Moje hydrozapadki i śruby powtarzalne! Świetnie się nadadzą. Dziękuję!', 0),
(1115, 'koKR', 'Chcesz wiedzieć coś o Nazzie Parowarze? To pilot wyścigowy z Migoczących Równin, prawda?$b$bTak, może zdołam się czegoś o nim dowiedzieć... ale to nie będzie łatwe. Ani szybkie.$b$bAni tanie.', 0),
(1117, 'koKR', 'No, no! To ciekawe... bardzo ciekawe. He, może następnym razem powinienem się pokłonić temu goblińskiemu pilotowi.$b$bTo jest warte majątek, $N. Na pewno Nazz zapłaci małą fortunę, żeby jego tajemnica pozostała... tajemnicą.', 0),
(1118, 'koKR', 'Rozumiem. Kravel planuje wielką intrygę. Ma przebiegły umysł – to w nim lubię.$b$bWięc potrzebujesz czegoś, co zamąci w głowie, tak? Czegoś mocnego...$b$bCiekawe, czy dałoby się wykorzystać miksturę, którą Zanzil karmi swoje zombie...', 0),
(1119, 'koKR', 'Wspaniale! Fizzlebub nie zawiódł! Zapamiętam mu to, kiedy go znów zobaczę.$b$bI dziękuję, $N. Świetnie ci idzie, a na tym interesie możemy sporo zarobić...', 0),
(1120, 'koKR', 'Stout? Jakie to miłe! Dziękuję!$b$bNie powinniśmy pić przed wyścigiem, ale... może moim chłopakom przyda się łyczek. Zresztą nie może być aż taki mocny, prawda?', 0),
(1121, 'koKR', 'Co my tu mamy? Gorzała, co?$B$BNo cóż, po jednym małym chyba nie zaszkodzi...', 0),
(1122, 'koKR', 'Piszą tu, że stout głupca okazał się sukcesem. To dobra wiadomość!$b$bJeśli kiedyś zechcesz więcej tego trunku, daj mi znać, a poproszę cię o zebranie kolejnej porcji mikstury Zanzila.', 0),
(1137, 'koKR', '$N, $gwróciłeś:wróciłaś;! $GZnalazłeś:Znalazłaś; Marteka? $GRozmawiałeś:Rozmawiałaś; z nim? Co powiedział? Może pomóc??$b$bMów, mów, mów!!', 0),
(1147, 'koKR', 'Ha! Ta posoka, którą jesteś $goblepiony:oblepiona;, właściwie dodaje ci urody, $N! Ale przy okazji cuchniesz jak diabli. Nie stój za blisko kodo – albo wywołasz popłoch, albo wprawisz je w ruję.$B$BMyślę, że moi towarzysze się zgodzą, że już sam twój zapach dowodzi, że $gpomogłeś:pomogłaś; nam w walce z tymi owadami. Dziękuję, $N.', 0),
(1149, 'koKR', 'Dopiero w obliczu niespodziewanych przeciwności zaczynamy dostrzegać, jak silny jest nasz duch. $GWykonałeś:Wykonałaś; skok wiary, choć nic nie gwarantowało, że przeżyjesz. Twój umysł jest otwarty, a duch gotowy na to, co nadejdzie.$b$bJeśli zechcesz, czeka na ciebie kolejna próba.', 0),
(1150, 'koKR', 'Grenka była potężna, nawet jak na trolla. Możesz być $gdumny:dumna; z tego, czego dziś $gdokonałeś:dokonałaś;.$b$bPodczas próby wiary $gwykazałeś:wykazałaś; się siłą ducha, a teraz $gpokazałeś:pokazałaś; wytrzymałość w walce, stawiając czoła harpiom z Nory Łotrzych Piór. Nadszedł jednak czas na nową próbę.', 0),
(1151, 'koKR', 'Próba siły dobiegła końca. $GWykazałeś:Wykazałaś; się siłą i odwagą i jesteś teraz $ggotów:gotowa; na ostatnią próbę, która zwieńczy te obrzędy.', 0),
(1175, 'koKR', 'Mam nadzieję, że nie $gzabiłeś:zabiłaś; żadnego bazyliszka na samym torze! Truchła długo rozkładają się w słońcu, a wolałbym nie musieć sprzątać ich łopatą.', 0),
(1176, 'koKR', 'Świetnie! Od razu zagonię ekipę do roboty. Dzięki, $N!', 0),
(1181, 'koKR', 'Och, jasne, oczywiście, że wiem, o czym mówisz. Ale nie, nie mogę ci pomóc. Kilku moich ludzi miało wytropić plany regulatora paliwa, ale wrócili z pustymi rękami.', 0),
(1182, 'koKR', 'Pozwól tylko, że zrobię sobie kopię tych planów do moich notatek, a potem możesz je zanieść prosto Pozzikowi. Nie chciałbym, żeby pomyślał, że któryś z jego sponsorów go porzuca.', 0),
(1183, 'koKR', 'Liczyłem, że będzie już złożony, ale dzięki temu mam wyjątkową okazję, by ulepszyć projekt od podstaw. Dzięki, $N. Naszkicuję ulepszone schematy, zbuduję to cudo i wkrótce je zamontuję.', 0),
(1186, 'koKR', 'To ty pomagasz Pozzikowi, prawda? Kiedyś byłem taki jak ty – biegałem po boksach serwisowych i pomagałem przy każdej robocie, jaką mechanicy pozwolili mi wykonać.$b$bA teraz spójrz na mnie! Niezrównany pilot goblińskiej drużyny wyścigowej!', 0),
(1187, 'koKR', 'Tylko spójrz na tę ślicznotkę! Piętnaście funtów czystej mocy seaforium! Jak tylko przypnę to do boku wyścigówki, będę śmigał po torze tak szybko, że pokonam gnomy dwa razy!', 0),
(1188, 'koKR', 'Tylko Razzeric mógł na to spojrzeć i stwierdzić, że założyłem jakąś blokadę. Ten dopalacz to niemal w całości materiał wybuchowy z seaforium. Już go przerobiłem, żeby przy użyciu uwalniał większą część ładunku, ale Razzeric nigdy nie jest zadowolony, dopóki nie podkręci wszystkiego na jedenastkę!', 0),
(1189, 'koKR', 'No, teraz to rozumiem! Chciałbym zobaczyć miny gnomów, kiedy zobaczą, jak odpalam tę ślicznotkę.$b$bSzkoda, że będę zbyt zajęty biciem nowego rekordu toru!', 0),
(1190, 'koKR', 'Zwój notatek i projektów dotyczących rafinacji jakiegoś surowca, nabazgranych w wielkim pośpiechu.', 0),
(1191, 'koKR', 'Ruszajmy!', 0),
(1192, 'koKR', 'Wyśmienicie! Od razu zagonię ekipę do pracy nad częściami, których będziemy potrzebować na następny wyścig.', 0),
(1194, 'koKR', 'Indurium? Ciekawe... Jeśli rzeczywiście jest tak odporne na żar, jak mówisz, to wyjaśniałoby, czemu gnomy ostatnio osiągają lepsze wyniki.$B$BTa próbka, którą $gprzyniosłeś:przyniosłaś;, też będzie bezcenna. Będę mógł przeprowadzić na niej kilka testów, ale żeby naprawdę nam się przydało, potrzebuję go więcej.', 0),
(1949, 'koKR', 'Co? Mów głośniej! Te stare uszy nie słyszą już tak dobrze jak kiedyś.$B$BMam nadzieję, że $gprzyszedłeś:przyszłaś; ze świeżym kuflem piwa albo gorącymi typami na następny wyścig! Jeśli nie, to lepiej idź dalej... bo mam tu różdżkę polimorfii z twoim imieniem!', 0),
(1950, 'koKR', 'Ach, teraz sobie przypominam...$B$BZapomniałem o tej drobnej klątwie, którą rzuciłem na Johnsona. Nie pamiętam, czemu to zrobiłem, ale na pewno sobie zasłużył, niewdzięcznik jeden!', 0),
(1951, 'koKR', 'To ta! Dokładnie tego potrzebuję, żeby przygotować się do rytuału stworzenia twojej różdżki! Mam nadzieję, że jej odnalezienie nie sprawiło ci zbyt wiele kłopotu...', 0),
(2770, 'koKR', 'Rany, $gzdobyłeś:zdobyłaś; łuskę! Dzięki, $N. Nie mogę się doczekać, aż się za nią zabiorę!$B$BTo $gwidziałeś:widziałaś; Gahz\'rillę? Był tak wielki, jak mówią??', 0),
(3841, 'koKR', 'Ach, jajo duszkowca, i to bliskie wyklucia, jeśli się nie mylę. Niezwykłe, że $gznalazłeś:znalazłaś; takie, a co dopiero w tak dobrym stanie. W Feralas rzadko się je dziś widuje. Z tego, co wiem, w okolicy grasowali kłusownicy, którzy z różnych powodów próbowali je chwytać i zabijać. Wielka szkoda... to takie piękne stworzenia, gdy dorosną.$B$BJak $gwszedłeś:weszłaś; w posiadanie takiego znaleziska?', 0),
(3842, 'koKR', 'Wspaniale. Świetnie się nadadzą. Daj mi chwilę na zmieszanie składników, a zobaczymy, jak się miewa to jajo.', 0),
(3843, 'koKR', 'No, no, no... Nie widziałem czegoś takiego od wieków, i to smoczych. Smok wróżek, jeśli się nie mylę... wygląda na odmianę duszkowca. Znakomicie, doprawdy znakomicie.$B$BNo, jeśli ten maluch ma się wykluć i wyrosnąć na silnego i zdrowego, trzeba mu zdobyć coś do jedzenia. Dobrze, że $gzdążyłeś:zdążyłaś; z nim do mnie na czas.', 0),
(4542, 'koKR', 'Kolejne złe wieści! Te centaury posunęły się za daleko! Napadły na jedną z moich karawan z zaopatrzeniem i wyrżnęły cały oddział. To oburzające i nie ujdzie im na sucho!$b', 0),
(4767, 'koKR', 'Doskonale! Dzięki tym jajom mam nadzieję zrobić kolejny krok, by zostać jeźdźcem wiwern. Oto dowód mojej wdzięczności. Niech zawsze sprzyjają ci udane łowy, $N.', 0),
(4770, 'koKR', 'Co?! Gdybym wiedział, że Pao\'ka Rącza Góra będzie węszyć po Wysokiej Grzędzie, przykułbym go łańcuchem do totemu! Jego ojciec niechętnie pozwolił mu wyruszyć ze mną do Tysiąca Filarów. Przybyliśmy tu badać różne stworzenia zamieszkujące te piękne ziemie.$b$bDoceniam pomoc, której $gudzieliłeś:udzieliłaś; Pao\'ce. Mam nadzieję, że to wynagrodzi ci wszelkie straty, jakie przez to $gponiosłeś:poniosłaś;.', 0),
(4821, 'koKR', 'Tak, nareszcie... tajemnicze jajo w końcu do mnie dotarło. A teraz przyjrzyjmy mu się bliżej... Co...! Co to jest...?$b', 0),
(4841, 'koKR', 'W dowód mojej wdzięczności – to dla ciebie, $N.', 0),
(4865, 'koKR', 'Pomsta! A więc legenda o Arikarze jest prawdziwa. To rzeczywiście problem, który trzeba natychmiast rozwiązać.', 0),
(4881, 'koKR', 'Przyjdą mnie zabić? Pokażę im, jak walczy tauren!', 0),
(4904, 'koKR', 'Dziękuję ci, $N. Czułam w kościach, że odnajdzie drogę do mnie. Opowiedziała mi o twojej odwadze i o tym, jak $gpomogłeś:pomogłaś; jej uciec. Te przedmioty należały do jej brata. Wiem, że chciałaby, żeby trafiły do ciebie.', 0),
(4966, 'koKR', 'Dziękuję za pomoc, $N. Bez ciebie nie zdołałbym ich powstrzymać.', 0),
(5064, 'koKR', 'Na Wielki Totem Ducha! To naprawdę złe wieści. Muszę zacząć przygotowania na to, co może nadejść.$b$b$N, zgodnie z obietnicą oto nagroda za twoją dzielną służbę.$b$b', 0),
(5147, 'koKR', 'Ha! To doskonała wiadomość! Zaczynałem już myśleć, że nigdy nie poniesie kary!$b$bProszę, $N... i dziękuję. Na wieść o nikczemnych czynach Arnaka krew się we mnie gotowała!', 0),
(5151, 'koKR', 'Mój hiperkondensator! Będę miał zajęcie na jakiś czas, zanim rozgryzę, do czego on służy...', 0),
(5762, 'koKR', 'Świetnie, moja paczka od Węglobrodego! Dziękuję, $N. W tej skrzynce jest amunicja specjalnego kalibru, która przyda nam się w dżungli!$b$bOto twoja zapłata. I powiedz mi, jak się miewa stary zrzęda Kravel? Pewnie dalej coś kombinuje...', 0),
(9431, 'koKR', 'Co? Nie wspomniała o księżycowej studni? Przecież od początku o to jej chodziło. Przyznaję, cała sprawa jest trochę zwariowana, ale kim jestem, żeby odprawiać klientkę, zwłaszcza jeśli to moja jedyna klientka?$B$BMoże zakradanie się do osady nocnych elfów i kradzież wody z ich księżycowej studni to nie najrozsądniejsza rzecz, w jakiej kiedykolwiek pomogłem klientowi, ale jej złoto jest tak samo dobre jak każde inne!', 0),
(9433, 'koKR', 'Zadziałało lepiej, niż się spodziewałem! Kolejny punkt dla starej, dobrej goblińskiej pomysłowości!$B$BJedyny problem w tym, że jest beznadziejnie zakurzony! Wyczyszczenie tego ustrojstwa i zapakowanie go z powrotem do skrzyni zajmie mi wieki.$B$BOczywiście czasu mam pod dostatkiem.', 0),
(9434, 'koKR', 'Doskonale, wygląda na to, że niczego nie brakuje. Teraz muszę tylko wszystko wymieszać i spróbować. Jeśli ten tonik zadziała tak, jak wskazują moje badania, być może odkryłam sposób na złagodzenie skutków uzależnienia mojego ludu od magii.$B$BNa twoich oczach tworzy się historia, $N. Pomyśl tylko: bez twojej pomocy nie byłoby to możliwe.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(1100, 'koKR', 'Po twojej zatroskanej minie widzę, że coś jest nie tak...', 0),
(1104, 'koKR', 'Cześć, cześć, cześć! Masz ten jad??', 0),
(1105, 'koKR', 'Mój brat robi postępy z nowym paliwem i to mnie martwi. Muszę jak najszybciej zabrać się za zbiornik paliwa z żółwiej skorupy!', 0),
(1106, 'koKR', 'No, $gznalazłeś:znalazłaś; mnie. Brawo.$b$bPrzychodzisz w sprawie topora, który zrobiłem dla Gath\'Ilzogga? A może chcesz pomścić honor księżnej Pamay?$b$bW sumie nie obchodzi mnie, o co chodzi. Jeśli $gprzyszedłeś:przyszłaś; walczyć, to miejmy to z głowy...', 0),
(1107, 'koKR', 'Masz płetwy ogonowe? Jeśli nie ochronię naszego samochodu przed jego własną prędkością, nie wytrzyma długo w tych wyścigach.', 0),
(1108, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś płatki indurium, $N? Rozgrzałem kuźnię i jestem gotów je zbadać.', 0),
(1110, 'koKR', '$N, $gbyłeś:byłaś; na Równinach? $GPrzyniosłeś:Przyniosłaś; ten ładunek części, o który prosiłem?', 0),
(1114, 'koKR', 'Masz coś dla mnie? Super! Pokaż!', 0),
(1117, 'koKR', '$GZdobyłeś:Zdobyłaś; coś na Nazza Parowara? Coś, co wolałby zachować w tajemnicy??', 0),
(1118, 'koKR', 'Witaj, witaj. A co sprowadza kogoś tak szlachetnego jak ty do Łupieżczej Zatoki?', 0),
(1119, 'koKR', 'Witaj, $N. Fizzlebub zdołał nam pomóc?', 0),
(1120, 'koKR', 'Cześć! Masz coś dla mnie?', 0),
(1121, 'koKR', 'Na co się gapisz?', 0),
(1122, 'koKR', 'Witaj, $N. Jak się sprawdził ten stout? Mocny, co?', 0),
(1147, 'koKR', 'Przy tylu podróżnych ciągnących na Równiny na te wyścigi na pewno przekonamy dość poszukiwaczy przygód, żeby pomogli odepchnąć te owady. Ja i mój oddział nie będziemy mogli odejść, dopóki się to nie uda.', 0),
(1149, 'koKR', 'Wiara. Jest o wiele ważniejsza, niż niektórzy sądzą.$B$BCzasem nie ma znaczenia, w co wierzysz. Ważne jest po prostu, żeby w coś wierzyć.', 0),
(1150, 'koKR', 'Musisz być $gprzygotowany:przygotowana; duchowo, fizycznie i umysłowo na wyzwania, które cię czekają.$b$bZbyt często rzucamy się naprzód, zanim jesteśmy gotowi. Uważam za swój obowiązek wobec młodych, bez względu na to, z jakiego plemienia pochodzą, przygotować ich na niebezpieczeństwa, które mogą napotkać, gdy opuszczą bezpieczne domowe progi.', 0),
(1151, 'koKR', 'Centaury z plemion Tysiąca Filarów nazywają Rok\'Alima także Miażdżycielem – od grzmotu, z jakim jego pięści spadają na stworzenia na tyle odważne, albo głupie, by stanąć mu na drodze.', 0),
(1175, 'koKR', 'Wystarczy, że muszę uprzątać wraki wyścigówek, a jeszcze wygrzebywać je spośród spalonych szczątków zwierząt.', 0),
(1176, 'koKR', 'Masz dla mnie te kości? Właśnie miałem się zabrać do odchudzania układu kierowniczego, ale nie chcę go rozbierać, dopóki nie mam wszystkich potrzebnych części.', 0),
(1182, 'koKR', 'Choć niechętnie to przyznaję, ta gnomia drużyna jest całkiem dobra. Nasi chłopcy potrzebują każdej przewagi, jaką mogą zdobyć.', 0),
(1183, 'koKR', '$N! $GZdołałeś:Zdołałaś; wytropić regulator paliwa?', 0),
(1187, 'koKR', 'Jak mam się pokazać na torze bez małego dodatkowego kopa? To skandal, mówię ci.', 0),
(1188, 'koKR', 'Jak zapewne wiesz, Gadżetorium zaspokoi wszystkie twoje majsterkowiczowskie potrzeby! W czym mogę pomóc?', 0),
(1189, 'koKR', 'Wyobrażasz sobie, że Pozzik wstawił do wyścigówki wiadro piasku? Jak mam osiągnąć maksymalną prędkość z wiadrem piasku pod siedzeniem?', 0),
(1192, 'koKR', 'Chciałbym wbudować indurium w różne części naszych wyścigówek, ale do wykonania tych części potrzebuję dużych ilości surowego indurium.$B$BRudę indurium znajdziesz w wykopaliskach Uldamanu na Bezludziu, za morzem, w Khaz Modan.$B$BGnomy zdobywają własne zapasy, więc musimy mieć swoje, żeby dotrzymać im kroku.', 0),
(1950, 'koKR', 'Na co czekasz? Potrzebuję mojej magicznej formuły!', 0),
(1951, 'koKR', 'Witaj, $N. $GZnalazłeś:Znalazłaś; księgę „Rytuały mocy”?', 0),
(2770, 'koKR', 'Masz łuskę? Nie mogę się doczekać, aż wypróbuję różne sposoby okiełznania jej energii!', 0),
(3841, 'koKR', 'Ależ witaj, $N.$B$BNiech cię nie zmyli to, gdzie jestem – naprawdę nie przyjechałem tu dla wyścigów... choć są bardzo zajmujące.$B$BTak naprawdę jestem tu, w Tysiącu Filarów, i badam wszystko, co się da, by ustalić, na ile tę ziemię da się ocalić. Stało się to dla mnie swego rodzaju krucjatą – ożywić tę okolicę i wzbogacić ją nową, żyzną glebą. Może się okaże, że w pobliżu jest jakieś źródło wody.$B$BNie mów, że nie $gzauważyłeś:zauważyłaś;, jak dziwne jest przejście między Feralas a Tysiącem Filarów. Gdy do tego doszło, działała tu jakaś dziwna magia.', 0),
(3842, 'koKR', 'Im dłużej tu jestem, tym bardziej kusi mnie, żeby wziąć udział w tych wyścigach, $N. Doprawdy zdumiewające...$B$B$GZnalazłeś:Znalazłaś; już eliksiry? Gdy tylko ustalę, czy jajo będzie zdrowe, oddam ci je, byś się nim $gzaopiekował:zaopiekowała;, dopóki nie będzie gotowe do wyklucia.$B$BDaj mi znać.', 0),
(3843, 'koKR', 'Witajże, $N. Czym mogę ci służyć?', 0),
(4542, 'koKR', 'Czego chcesz, $N? Pilna wiadomość – dla mnie?$b', 0),
(4767, 'koKR', '$N, $gzdobyłeś:zdobyłaś; jaja wiwerny, których szukam? Nie mogę się doczekać szkolenia na jeźdźca wiwern!', 0),
(4821, 'koKR', 'Muszę dowiedzieć się więcej o tym tajemniczym jaju. Kto wie, co się z niego wykluje.', 0),
(4841, 'koKR', 'No, no, $N, wiem, że nie $gzabiłeś:zabiłaś; jeszcze tylu, ilu trzeba. Wytrop ich, a w dowód wdzięczności dam ci nagrodę.', 0),
(4904, 'koKR', 'Thalia Bursztynowa Skóra:', 0),
(5064, 'koKR', '$GOdkryłeś:Odkryłaś;, co knują Ponure Totemy?', 0),
(5147, 'koKR', 'Masz jakieś wieści o tym mordercy, Arnaku Ponurym Totemie?', 0),
(5151, 'koKR', 'Masz mój hiperkondensator?', 0),
(5762, 'koKR', 'Czy to pustynny pył na twoim kołnierzu?$b$bHm... jeśli nos mnie nie myli, to nie pustynny pył, tylko pustynna sól! $GByłeś:Byłaś; na Migoczących Równinach, co?', 0),
(9431, 'koKR', 'Liścik magistrix Elosai był nieco zagadkowy, ale chyba rozumiem, czego ode mnie chce. Jeśli masz ziemię, o której mówiła, mogę umieścić ją w naczyniu, którego będziesz potrzebować na wodę z księżycowej studni.', 0),
(9433, 'koKR', 'Spisał się?', 0),
(9434, 'koKR', 'Udało się wam z Wizlem zebrać składniki?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(715, 0, 'koKR', 'Kolejny piękny dzień w dżungli! To będą wspaniałe łowy, czuję to. Gdy tylko Barnil skończy czyścić strzelby, zabieram grupę łowiecką w głąb splątanych pnączy. Niezły sposób na emeryturę dla starego weterana, co?', 0),
(773, 0, 'koKR', '$C, co? Jestem Krazek, sekretarz barona Revilgaza. Wiem wszystko o tym, co się dzieje w tej dżungli i poza nią. Może chcesz poznać aktualną cenę ropy w Zapadce? Nie? A może szukasz pracy? W tym mogę pomóc.', 0),
(2498, 0, 'koKR', 'Co, co?!? Wszyscy musimy zarabiać... a stojąc bezczynnie, nic nie zarobimy.', 0);
