INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(424, 'koKR', '--Dzień pierwszy--\n\nPodróż z Żelaznej Kuźni wreszcie przywiodła mnie do Kalimdoru!\n\nPoszukiwacz Khazgorm z Bael Modan robi wielkie postępy. Odkrył dziś skamieniałość, którą uczeni z wykopaliska uważają za fragment kości starożytnego boga. Khazgorm jest pewien, że skamieniałość to część większej zagadki. Sam nadzoruje wykopalisko, a mnie powierzył zadanie odnalezienia kolejnych skamieniałości, które pozwolą złożyć tę historię w całość.\n\nMoje zadanie: ruszyć na południe w poszukiwaniu kolejnych wskazówek.', 0),
(425, 'koKR', '--Dzień drugi--\n\nZiemie Pustkowi są rozległe i bezkresne. Moja wędrówka była długa i żmudna i jak dotąd nie przyniosła niczego, co zainteresowałoby archiwa Ligi Odkrywców.\n\nJedyne godne uwagi zdarzenie miało miejsce w pobliżu Złotej Drogi. W oddali dostrzegłem jakieś dziwne stworzenia. Wyglądały na pół świnie, pół ludzi. Szybko się ukryłem i przepuściłem te plugawe bestie. Ależ smród po sobie zostawiły!', 0),
(426, 'koKR', '--Dzień trzeci--\n\nO, wielkie i wspaniałe odkrycie!\n\nPodczas dzisiejszych poszukiwań natrafiłem na niezwykłe znalezisko: ogromne szczątki czegoś, co wyglądało na stworzenie podobne do dzika. Jego czaszka wznosiła się wysoko nade mną. Przy każdym zębie tej bestii nawet olbrzym wyglądałby jak karzeł... a co dopiero krasnolud. Ze względu na sam rozmiar znaleziska skłaniam się ku przekonaniu, że to szczątki jednego z Przedwiecznych, o których krążą pogłoski.', 0),
(427, 'koKR', 'Jakiś czas temu, w siedzibie Ligi Odkrywców w Żelaznej Kuźni, słuchałem wykładu głównego archeologa Siwowąsa. Staruszek wspomniał o takim bogu, czczonym przez dziwne elfy z Darnassus za jego rzekomo szlachetną naturę –\n\nPsiakość! Chwileczkę. Słyszę parskanie przed namiotem. Pewnie to tylko ostowe dziki dobierają się do mojego zapasu jabłek...', 0),
(428, 'koKR', '--Dzień 4--\n\nPojmany!\n\nMuszę... pisać... szybko.\n\nNapadli mnie dzikoludzie z plemienia Brzytwoskórych. Sądziłem, że prowadzą mnie do wielkich szczątków upadłego boga-dzika. Zamiast tego ominęli ogromne skamieniałości i ruszyli prosto na zachód od olbrzymiej czaszki, przez Złotą Drogę.', 0),
(429, 'koKR', 'Brutalnie zawleczony do cuchnącego, zarośniętego cierniami gąszczu zwanego Cierniskiem Brzytwoskórych. Wrzucony do prymitywnie skleconej chaty i uwięziony razem z umierającym nocnym elfem.\n\nNie mam przy sobie nic poza tym dziennikiem, piórem i zegarkiem kieszonkowym...\n\nKtoś nadchodzi...', 0),
(430, 'koKR', '--Dzień 5--\n\nMój współwięzień, nocny elf, cierpi z powodu ciężkich ran. Dzikoludzie wielokrotnie go chłostali i obawiam się, że wkrótce umrze, chyba że jakimś cudem oddział ratunkowy odważy się zapuścić w to zdradliwe miejsce. Raz po raz traci i odzyskuje przytomność. Gdy się budzi, staram się dać mu tę odrobinę wody, którą mam.', 0),
(431, 'koKR', 'Zeszłej nocy po raz pierwszy zdołał przemówić. Jest druidem, nazywa się Heralath i przysłano go tu, by zbadał pogłoski o upadłym bogu-dziku.\n\nSłabym głosem powiedział mi, że jego zdaniem wielka dzicza czaszka znaczy miejsce, w którym wielki bóg-dzik Agamaggan poległ w walce z Płonącym Legionem jakieś 10 000 lat temu, podczas Wojny Starożytnych. Jego potężne cielsko spłaszczyło ziemię, a krew wsiąkła w glebę. Tam, gdzie spadła jego krew, rosną poskręcane iglice cierni...', 0),
(432, 'koKR', 'Heralath i jego pobratymcy chcą odkryć źródło skażenia w tym miejscu. Powiedział mi, że Agamaggan uchodził za czystego boga. Dlaczego te plugawe stwory i złowrogie ciernie szpecą tę ziemię, pozostaje prawdziwą zagadką.\n\nZanim zdążyłem wypytać go o więcej, Heralath znów zapadł w niespokojny sen...', 0),
(433, 'koKR', '--Dzień 6--\n\nStan Heralatha się pogarsza.\n\nOtworzył dziś oczy tylko raz. Mówił z bolesnym trudem, ale jego przesłanie było jasne. Jeśli uda mi się uniknąć zguby tu, w Ciernisku Brzytwoskórych, muszę przekazać Falfindelowi Strażnikowi Szlaków w Thalanaar, że Charlga Brzytwoboka zbiera sługi na południu Pustkowi. Jej moc rośnie z każdym dniem. Wiedźmę trzeba powstrzymać, zanim plaga skażenia rozprzestrzeni się z Cierniska.', 0),
(434, 'koKR', 'Biedny Heralath jest blady jak kość. Gorączka rośnie z minuty na minutę. Tymczasem dzikoludzie szykują się do jakiejś wielkiej wyprawy wojennej. Obawiam się, że jeśli wkrótce nie spróbuję uciec, spotka mnie los podobny do losu mojego elfiego współwięźnia.\n\nZamierzam wymknąć się, gdy dzikoludzie wyruszą na następne łowy. Strażnicy są leniwi i często przesypiają swoje warty.', 0),
(435, 'koKR', 'Gdy wydostanę się z Cierniska, ruszę w stronę Tysiąca Filarów, a potem na zachód, do Thalanaar na granicy tajemniczego lasu Feralas. Tam odszukam druida znanego jako Falfindel Strażnik Szlaków.\n\nTo, co zaczęło się jako próba zbadania przeszłości mojego ludu, przerodziło się w coś znacznie większego. Bezpieczeństwo Przymierza spoczywa w moich rękach...', 0),
(438, 'koKR', 'Goblin Nazz Parowar jest w rzeczywistości synem goblińskiego księcia kupieckiego (którego księcia? Cena tej informacji jest wysoka).$B$BWygląda na to, że znacznie bardziej woli wydawać pieniądze zarabiane przez rodzinę, niż zarabiać je sam. Ukradł więc z rodzinnego skarbca niemałą fortunę i teraz ukrywa się na Migoczących Równinach.$B$BGdyby jego ojciec wiedział, gdzie on jest, na pewno by go odszukał i zawlókł z powrotem do domu... bez jednego palca u nogi, za karę za zuchwałość.', 0),
(439, 'koKR', 'Panie Fizzlebub,$B$Bdoręczyciel tego listu i ja planujemy przedsięwzięcie, do którego chętnie Pana zaprosimy. $B$BJak Pan wie, spędzam sporo czasu na Migoczących Równinach, a wspomniane przedsięwzięcie dotyczy wyścigów na tych równinach.$B$BJeśli wyścigi, a zwłaszcza zakłady na wyścigach, Pana interesują, proszę czytać dalej, bo sądzę, że Pańska znajomość Cierniodławów przyda się w naszym planie.', 0),
(440, 'koKR', 'Panie Fizzlebub, napój, który dał Pan mojemu wspólnikowi, okazał się wielkim sukcesem. Nie dość, że jest mocny i porządnie otępia, to jeszcze wygląda na to, że uzależnia. Jestem pewien, że ci, którzy go spróbowali, będą chcieli więcej. Jesteśmy Pana dłużnikami, Crank. Zapraszam Pana na Migoczące Równiny – albo proszę przysłać zaufaną osobę – by skorzystać z nowych okazji do hazardu, jakie tu mamy. --Kravel', 0),
(441, 'koKR', 'Drogi Marteku,$B$Bmam kłopot i potrzebuję twojej pomocy.$B$BRazem z bratem budujemy samochód wyścigowy i potrzebujemy mocnych tłoków. Nic, czego próbuję, nie jest dość twarde. Nic nie wytrzymuje prędkości naszego nowego samochodu. Dlatego silnik ciągle się psuje!$B$BJesteś mistrzem w obróbce metalu. Musisz pomóc. Tylko ty możesz.', 0),
(445, 'koKR', 'Samochody rakietowe ścigające się na równinach są precyzyjnie wyregulowane i wymagają wyjątkowo starannej obsługi. Nic więc dziwnego, że ekipy serwisowe są na miejscu przez cały czas. $B$BEkipy te nieustannie testują swoje samochody i w razie potrzeby wprowadzają poprawki i modyfikacje. Tylko tak można utrzymać samochody w szczytowej formie.$B$BSzukamy więc sposobu, by wywołać chwilę nieuwagi u jednej z ekip serwisowych, bo każde takie zaniedbanie sprawiłoby, że ich samochód szybko by się rozsypał.', 0),
(446, 'koKR', 'Jeśli będziemy decydować, który samochód jest w najlepszej formie, a który nie, to... nie muszę Panu tłumaczyć, jaką przewagę da nam to w zakładach.$B$BDlatego od Pana, dobry Fizzlebubie, potrzebujemy środka, który wywoła nieuwagę ekip serwisowych.$B$BCzy w Cierniodławach jest jakaś roślina, zioło albo napój, którym moglibyśmy zamącić w głowach gnomom i goblinom?$B$B--K. Węglobrody', 0),
(751, 'koKR', 'Oto specyfikacja tłoka:$B$BDługość: 32 SW$BSzerokość: 12 SW$BWaga: od 23,5 MG do 25,5 MG$BPrzewodność: 70 PP$BWytrzymałość na ścinanie: 98 lub więcej$BWskaźnik kombobulacji: „superkrzepki” lub wyższy$B$BGdybyś zapomniał gnomich jednostek miary:$BSW = „szerokość wąsa”$BMG = „malusieńkie gramy”$BPP = „podkurcze palców”', 0),
(1711, 'koKR', 'Pilna wiadomość do wartownika urwisk Długoroga$b$bDuży oddział centaurów z Obozu E\'thok napadł na jedną z naszych karawan z zaopatrzeniem. Zginęli wszyscy członkowie karawany i przepadły wszystkie zapasy. To był zuchwały, bezprecedensowy atak centaurów i obawiam się, że nie ostatni.', 0),
(1771, 'koKR', 'Ta pamiątka z Drugiej Wojny dobitnie przypomina, jak niebezpiecznie blisko była Horda zdobycia Góry Żelaznej Kuźni.', 0),
(2232, 'koKR', 'Agashamie,$b$bnasze plany muszą za wszelką cenę pozostać w tajemnicy! Jeśli pozostałe plemiona taurenów odkryją nasze powiązania, będzie to katastrofa.$b$bPodpisano,$b$bZwiastun Elm', 0),
(2233, 'koKR', 'Agashamie,$b$bgdy połączymy siły, będziemy potężniejsi niż wszystkie plemiona taurenów razem wzięte! Wymagamy jednak twojego całkowitego posłuszeństwa. Pamiętaj, twój lud zostanie nagrodzony dopiero wtedy, gdy nasze plany się ziszczą!$b$bPodpisano,$b$bZwiastun Rex', 0),
(2234, 'koKR', 'Agashamie,$b$bnasi agenci z Lordaeronu wkrótce spotkają się z twoimi wysłannikami. Powiadomimy cię, gdy znajdziemy odpowiednie miejsce na nasze spotkanie na szczycie.$b$bPodpisano,$b$bZwiastun Grakus', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1452, 'koKR', 'Wyścig rozpocznie się za minutę!', '', 0),
(1468, 'koKR', 'Hm... jeśli chcesz komuś namieszać w głowie, $n, to sekret zombie Zanzila może się sprawdzić!', '', 0),
(1469, 'koKR', 'Dziękuję, $n.', '', 0),
(1470, 'koKR', 'Na pewno znajdę zastosowanie dla tej mieszanki...', '', 0),
(1495, 'koKR', '%s słucha, jak $n opowiada mu o swoich przygodach na Bezludziu.', '', 0),
(1496, 'koKR', 'Zdumiewające! A więc kluczem jest indurium!', '', 0),
(1500, 'koKR', '%s zanosi płatki indurium do swojej kuźni.', '', 0),
(1501, 'koKR', 'A teraz podgrzejmy te płatki...', '', 0),
(1502, 'koKR', 'Na razie wytrzymują. Podkręćmy ogień...', '', 0),
(1503, 'koKR', 'Na Orgrima! To indurium wytrzymuje ogromny żar!', '', 0),
(1504, 'koKR', 'Próba udana! $n, to indurium to niesamowity materiał.', '', 0),
(1506, 'koKR', 'ŁUP! ŁUP! ŁUP! Podrasowuję samochód!!!', '', 0),
(1507, 'koKR', 'Gotowe!', '', 0),
(1509, 'koKR', 'Zakłady otwarte! Gobliński samochód prezentuje się świetnie i na pewno wygra! Obstawiajcie, zanim ruszy wyścig!', '', 0),
(1510, 'koKR', 'Mądrzy stawiają na gnomy w następnym wyścigu! Obstawiajcie, póki jeszcze możecie!', '', 0),
(1524, 'koKR', 'Hm, niezłe te kości tym razem, Pozzik.', '', 0),
(1525, 'koKR', 'Gotowe! Te przeróbki powinny trochę podkręcić prędkość, ale chyba nie zniesie zbyt wielu stłuczek.', '', 0),
(1537, 'koKR', 'Zwycięzcą wyścigu dragsterów jest... drużyna gnomów! Świetna robota, chłopaki!', '', 0),
(1538, 'koKR', 'Gobliny wygrywają wyścig dragsterów! Więcej szczęścia następnym razem, drużyno gnomów.', '', 0),
(1540, 'koKR', 'Hehehe! Wszystko robi bum!', '', 0),
(1541, 'koKR', 'Co to było?!', '', 0),
(1542, 'koKR', 'Psiakrew... To musiały być gobliny... Zobaczmy, jak duże są szkody.', '', 0),
(1543, 'koKR', 'Chyba nic więcej nie da się zrobić. Niech to szlag!', '', 0),
(1548, 'koKR', '%s wciąga nosem szczyptę pyłu snów...', '', 0),
(1549, 'koKR', '%s jest oszołomiony...', '', 0),
(1550, 'koKR', 'APSIK!', '', 0),
(1551, 'koKR', 'Ojej! $n, ten pył snów to mocna rzecz!', '', 0),
(2124, 'koKR', 'Wystartowali!', '', 0),
(2764, 'koKR', 'Jak dla mnie gobliny mają to w kieszeni. Mamy narzędzia i mamy talent!', 'Jak dla mnie gobliny mają to w kieszeni. Mamy narzędzia i mamy talent!', 0),
(2765, 'koKR', 'Gdyby nie to przeklęte gnomie szczęście, nigdy nie wygraliby żadnego wyścigu!', 'Gdyby nie to przeklęte gnomie szczęście, nigdy nie wygraliby żadnego wyścigu!', 0),
(2766, 'koKR', 'Radzę kupić gobliński bon wyścigowy. Kibicowanie drugiej drużynie to strata czasu.', 'Radzę kupić gobliński bon wyścigowy. Kibicowanie drugiej drużynie to strata czasu.', 0),
(2767, 'koKR', 'Ja stawiam na gobliny! A jeśli masz choć trochę rozumu, ty też!', 'Ja stawiam na gobliny! A jeśli masz choć trochę rozumu, ty też!', 0),
(2768, 'koKR', 'Podobno w następnym wyścigu chcą wysadzić samochód gnomów! Prawda czy nie, lepiej trzymać się z dala od ich stanowiska serwisowego.', 'Podobno w następnym wyścigu chcą wysadzić samochód gnomów! Prawda czy nie, lepiej trzymać się z dala od ich stanowiska serwisowego.', 0),
(2773, 'koKR', 'Och, chodzi ci o Johnsona? Podobno się ukrywa.', 'Och, chodzi ci o Johnsona? Podobno się ukrywa.', 0),
(2782, 'koKR', 'Ha! Tirth szuka go od wielu dni, ale on nie chce się dać znaleźć. Tchórzliwy z niego kurczak!', 'Ha! Tirth szuka go od wielu dni, ale on nie chce się dać znaleźć. Tchórzliwy z niego kurczak!', 0),
(2964, 'koKR', '„Dzielny” nie chce, żeby Tirth się dowiedział, że wciąż jest na Migoczących Równinach, więc zamienił się w kurczaka!$B$BJeśli znajdziesz „Dzielnego”, skiń na niego. Może wyjdzie z ukrycia.', '', 0),
(2968, 'koKR', 'Witaj na wyścigach! Miłego pobytu i nie stawiaj wszystkich pieniędzy na jedną kartę!', 'Witaj na wyścigach! Miłego pobytu i nie stawiaj wszystkich pieniędzy na jedną kartę!', 0),
(2969, 'koKR', 'Witaj, $N! Zapraszamy na wyścigi na Migoczących Równinach!', 'Witaj, $N! Zapraszamy na wyścigi na Migoczących Równinach!', 0),
(2970, 'koKR', 'Kto ma najszybszy samochód? Kto to wie?!?', 'Kto ma najszybszy samochód? Kto to wie?!?', 0),
(2971, 'koKR', 'Gobliński samochód ma potężnego kopa, ale gnomy ukryły w swoim jakąś sztuczkę czy dwie...', 'Gobliński samochód ma potężnego kopa, ale gnomy ukryły w swoim jakąś sztuczkę czy dwie...', 0),
(4079, 'koKR', '', 'Jestem gotowa, gdy tylko ty będziesz, $n. Prowadź!', 0),
(4080, 'koKR', '', 'Udało się! Spotkajmy się przy Jer\'kai, nad obozem Ponurego Totemu.', 0),
(4081, 'koKR', '', 'Nie! Smoki wróżek nie dają rady, $n! Muszę wrócić do Jer\'kai i upewnić się, że jej nie znaleziono. Niech Elune będzie z tobą.', 0),
(4122, 'koKR', '', 'Szybko! $n atakuje!', 0),
(4123, 'koKR', '', 'Giń, $n. Elune nie pozwoli ci dłużej krzywdzić jej stworzeń!', 0),
(4124, 'koKR', '', 'Śmierć ci, $n. Jak śmiesz podchodzić do mnie na strzał z łuku!', 0),
(4125, 'koKR', '', 'Śmiesz mnie dotykać?!', 0),
(5285, 'koKR', '', 'O nie! Skończył nam się czas.', 0),
(5648, 'koKR', 'Chodźmy, $n. Jestem gotów ruszać do Posterunku Białego Zasięgu.', '', 0),
(5654, 'koKR', 'O, tu wygląda znajomo. Jeśli będziemy dalej iść na wschód, chyba zdołamy... Aaa! Wiwerna atakuje!', '', 0),
(5683, 'koKR', 'Wielkie dzięki... Stąd już trafię do Posterunku Białego Zasięgu. Koniecznie porozmawiaj z Motegą Ognistą Grzywą, może zdołasz go przekonać, żeby nie odsyłał mnie do domu.', '', 0),
(5926, 'koKR', '', 'Miej się na baczności... Arnak ma jakąś dziwną władzę nad Ponurymi Totemami... nie spodoba im się, że uciekam.', 0),
(5927, 'koKR', '', 'Uważaj, Ponure Totemy nas dopadły!', 0),
(5928, 'koKR', '', 'Nadchodzą.', 0),
(5929, 'koKR', '', 'Nadciąga więcej Ponurych Totemów!', 0),
(5930, 'koKR', '', 'Nareszcie wolna... Muszę już iść. Dzięki, że $gpomogłeś:pomogłaś; mi uciec. Do Posterunku Wolnego Wiatru wrócę sama.', 0),
(6149, 'koKR', 'Nadchodzą! Brońcie się!', '', 0),
(8242, 'koKR', 'Patrzcie, co $n nam $gprzyniósł:przyniosła;! Pijemy!', '', 0),
(8244, 'koKR', '$n $gprzyniósł:przyniosła; nam gorzałę! Imprezka!', '', 0),
(8427, 'koKR', 'Szukasz „Dzielnego”? Cóż, $gnie słyszałeś:nie słyszałaś; tego ode mnie, ale... może jak zapytasz Kronkridera na wieży, to ci powie...', 'Szukasz „Dzielnego”? Cóż, $gnie słyszałeś:nie słyszałaś; tego ode mnie, ale... może jak zapytasz Kronkridera na wieży, to ci powie...', 0),
(9879, 'koKR', 'Leży tu sterta porozrzucanych papierów i schematów.', '', 0),
(9880, 'koKR', 'Tych papierów ktoś pilnuje. Porozmawiaj z Zamkiem, żeby odwrócił uwagę!', '', 0),
(11154, 'koKR', 'Witaj w Łupieżczej Zatoce, $gwspólniku:wspólniczko;. Mam nadzieję, że pobyt w moim mieście upłynie ci przyjemnie i bez wydarzeń – zwłaszcza bez wydarzeń. Trunków mamy pod dostatkiem, jeśli chce ci się pić, i wykidajłów też, jeśli cię nosi.$B$BA teraz... co ten skromny sługa Kartelu Parochlebców może dla ciebie zrobić? A jeszcze lepiej – co ty możesz zrobić dla mnie, hę?', '', 0),
(13508, 'koKR', '', '%s wyjmuje składniki ze skrzynki i miesza we flaszce po trochu każdego z nich.', 0),
(13509, 'koKR', '', 'Wiele przecierpiałam, by ukończyć badania, a dzięki twojej pomocy, $n, wreszcie mi się udało. Za lepszą przyszłość!', 0),
(13510, 'koKR', '', 'Kręci mi się... w głowie... Co... się ze mną dzieje?', 0),
(13511, 'koKR', '', 'Nie, to niemożliwe! Ten tonik... miał mnie wyleczyć z uzależnienia, a nie przyspieszyć mój upadek w szeregi Nędznych!', 0),
(14318, 'koKR', '', 'Tyle lat badań... i wszystko na nic! Może mieli rację, może musimy nauczyć się z tym żyć.', 0),
(14848, 'koKR', 'Ojciec wyruszył w bardziej egzotyczne strony w poszukiwaniu większej zwierzyny. Ale bez obaw, my tu dalej polujemy!', '', 0),
(27467, 'koKR', 'Witaj w Łupieżczej Zatoce, $gwspólniku:wspólniczko;. Nie przejmuj się DeMezą i jej załogą... raz w roku, w Dzień Piratów, pozwalamy tej diablicy szaleć, a potem zostawia nas w spokoju i znów rusza łupić Południowe Morza.$B$BA teraz... co ten skromny sługa Kartelu Parochlebców może dla ciebie zrobić? A jeszcze lepiej – co ty możesz zrobić dla mnie, hę?', '', 0),
(47240, 'koKR', 'Co cię sprowadza do bandy starych, wysłużonych pustynnych psów takich jak my?', '', 0);
